<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoría — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:980px;margin:auto;padding:82px 14px 32px}h1{margin:0}.sub{color:#64748b;margin:6px 0 18px}.filters,.panel{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:14px}.filters{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:8px;margin-bottom:12px}.filters input,.filters button{font:inherit;padding:10px;border:1px solid #cbd5e1;border-radius:10px}.filters button{background:#172033;color:#fff;font-weight:900}.event{padding:12px 0;border-bottom:1px solid #eef2f7}.event:last-child{border:0}.meta{display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:#64748b}.title{font-weight:900;margin-top:4px}.route{font-family:monospace;font-size:12px;color:#475569;margin-top:4px}.detail{font-size:12px;color:#64748b;margin-top:4px}@media(max-width:700px){.filters{grid-template-columns:1fr}.wrap{padding-left:12px;padding-right:12px}}</style></head><body><main class="wrap"><h1>Auditoría</h1><div class="sub">Registro automático de cambios y acciones sensibles.</div><div class="filters"><input id="u" placeholder="Usuario"><input id="e" placeholder="Entidad / API"><input id="d" type="date"><button id="b">Filtrar</button></div><section class="panel" id="list">Cargando…</section></main><script>const l=document.getElementById('list'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){const q=new URLSearchParams({usuario:document.getElementById('u').value,entidad:document.getElementById('e').value,desde:document.getElementById('d').value,limite:'150'}),r=await fetch('/api/auditoria.php?'+q),x=await r.json();if(!x.ok){l.textContent=x.error;return}l.innerHTML=x.eventos.length?x.eventos.map(v=>`<div class="event"><div class="meta"><span>${esc(v.created_at)}</span><span>${esc(v.usuario_nombre||'sistema')}</span><span>${esc(v.metodo||'')}</span><span>HTTP ${esc((JSON.parse(v.detalle||'{}').http_status)||'')}</span></div><div class="title">${esc(v.accion)} · ${esc(v.entidad)}</div><div class="route">${esc(v.ruta||'')}</div></div>`).join(''):'Sin eventos todavía.'}document.getElementById('b').onclick=load;load();</script></body></html>